"""The shared ``ProtectedString`` ships in the CLI wheel, which has no pydantic."""

import importlib
import sys

import pytest

from shared_anyscale_utils.utils.protected_string import ProtectedString


_MODULE = "shared_anyscale_utils.utils.protected_string"


@pytest.mark.parametrize(
    "hook",
    ["__get_validators__", "__modify_schema__", "__get_pydantic_core_schema__"],
)
def test_protected_string_carries_no_pydantic_hook(hook: str) -> None:
    assert not hasattr(ProtectedString, hook)


def test_protected_string_works_without_pydantic(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setitem(sys.modules, "pydantic", None)
    monkeypatch.setitem(sys.modules, "pydantic_core", None)
    monkeypatch.delitem(sys.modules, _MODULE, raising=False)
    monkeypatch.delitem(sys.modules, "shared_anyscale_utils.conf", raising=False)

    module = importlib.import_module(_MODULE)
    secret = module.ProtectedString("hunter2")

    assert secret == module.ProtectedString(secret)
    assert hash(secret) == hash(module.ProtectedString("hunter2"))
    assert secret != module.ProtectedString("other")
